import com.alibaba.fastjson2.JSONFactory;
import com.alibaba.fastjson2.reader.ObjectReaderProvider;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Test class for verifying the fix of casting org.bson.types.Decimal128 to Double.
 * This test uses reflection to avoid a hard compile-time dependency on the MongoDB driver.
 */
public class TypeUtilsDecimal128Test {

    @Test
    public void testCastDecimal128ToDouble() throws Exception {
        // Attempt to load org.bson.types.Decimal128 class via reflection
        // This avoids compilation errors if the MongoDB driver is not in the classpath
        Class<?> decimal128Class;
        try {
            decimal128Class = Class.forName("org.bson.types.Decimal128");
        } catch (ClassNotFoundException e) {
            // If MongoDB driver is not present, skip the test execution.
            // The test is considered passed (skipped) in this environment.
            return;
        }

        // Create a Decimal128 instance with a known value using reflection
        // Decimal128 typically has a constructor accepting BigDecimal or String
        BigDecimal testValue = new BigDecimal("123.45");
        Object decimal128Obj;
        try {
            // Try BigDecimal constructor first
            decimal128Obj = decimal128Class.getConstructor(BigDecimal.class).newInstance(testValue);
        } catch (NoSuchMethodException e) {
            // Fallback to String constructor if BigDecimal constructor is not available
            decimal128Obj = decimal128Class.getConstructor(String.class).newInstance(testValue.toString());
        }

        // Get the default ObjectReaderProvider
        ObjectReaderProvider provider = JSONFactory.getDefaultObjectReaderProvider();

        // Perform the cast using TypeUtils.cast
        // This invokes the patched code path specifically handling Decimal128 to Double
        Double result = TypeUtils.cast(decimal128Obj, Double.class, provider);

        // Verify the result is not null and matches the expected value
        assertNotNull(result, "Cast result should not be null");
        assertEquals(123.45, result, 0.0001, "Cast result should match the original Decimal128 value");
    }
}

