            contextAutoTypeBeforeHandler, 
            JSONReader.Feature.SupportAutoType
        );

        assertNotNull(paramsDTO1);
        assertNotNull(paramsDTO1.timeUnits);
        assertEquals(proxy.timeUnits, paramsDTO1.timeUnits);
